        <textarea id="textoOriginal" rows="8" placeholder="Exemplo: Este é um texto com a palavra X e o símbolo @ que deve ser retirado..."></textarea>

        <!-- 2. Entradas de Exclusão (5 campos) -->
        <label>Textos a serem removidos (máximo 5):</label>
        <div class="removal-inputs">
            <input type="text" class="remove-item" placeholder="Remover 1">
            <input type="text" class="remove-item" placeholder="Remover 2">
            <input type="text" class="remove-item" placeholder="Remover 3">
            <input type="text" class="remove-item" placeholder="Remover 4">
            <input type="text" class="remove-item" placeholder="Remover 5">
        </div>

        <!-- Botões de Ação -->
        <button id="processarBtn">⚙️ Processar e Remover Textos</button>
        <button id="copiarBtn">📋 Copiar Texto Limpo</button>

