        // 🚀 FUNÇÕES JAVASCRIPT EMBUTIDAS

        document.getElementById('processarBtn').addEventListener('click', processText);
        document.getElementById('copiarBtn').addEventListener('click', copyText);

        const textoOriginalInput = document.getElementById('textoOriginal');
        const resultadoTextoOutput = document.getElementById('resultadoTexto');
        const removeInputs = document.querySelectorAll('.remove-item');
        const feedbackMessage = document.getElementById('feedbackMessage');
        const copiarBtn = document.getElementById('copiarBtn');

        /**
         * Coleta os 5 itens de exclusão e aplica a remoção no texto original.
         */
        function processText() {
            const originalText = textoOriginalInput.value;
            let processedText = originalText;
            let removals = [];

            // 1. Coleta todos os textos a serem removidos, filtrando vazios
            removeInputs.forEach(input => {
                const item = input.value.trim();
                if (item !== "") {
                    removals.push(item);
                }
            });

            if (removals.length === 0) {
