                const regex = new RegExp(itemToRemove, 'g'); 
                processedText = processedText.replace(regex, '');
            });

            // 3. Atualiza a interface
            resultadoTextoOutput.value = processedText;

            // Mostra o botão de copiar e a mensagem de feedback
            copiarBtn.style.display = 'inline-block';
            feedbackMessage.style.display = 'block';
        }

        /**
         * Copia o texto do resultado para a área de transferência do usuário.
         */
        function copyText() {
            const textToCopy = resultadoTextoOutput.value;

            // Utiliza a API moderna de Clipboard
            navigator.clipboard.writeText(textToCopy).then(() => {
                alert("🎉 Texto limpo copiado com sucesso para a área de transferência!");
                // Opcional: esconde a mensagem de feedback após a cópia
                feedbackMessage.style.display = 'none';
            }).catch(err => {
                // Fallback para navegadores mais antigos (método execCommand)
                resultadoTextoOutput.select();
                document.execCommand('copy');
                alert("🎉 Texto limpo copiado com sucesso (usando método de fallback)!");
            });
        }

    </script>
